"use strict";

function parse(value) {
  const match = /^v?(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/.exec(String(value).trim());
  if (!match) {
    return null;
  }
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
  };
}

function format(parsed) {
  return parsed.major + "." + parsed.minor + "." + parsed.patch;
}

function compare(left, right) {
  return left.major - right.major || left.minor - right.minor || left.patch - right.patch;
}

function valid(value) {
  const parsed = parse(value);
  return parsed ? format(parsed) : null;
}

function satisfies(value, range) {
  const parsed = parse(value);
  if (!parsed) {
    return false;
  }
  const wanted = String(range || "*").trim();
  if (wanted === "*" || wanted === "") {
    return true;
  }
  if (wanted[0] === "^") {
    const base = parse(wanted.slice(1));
    return !!base && parsed.major === base.major && compare(parsed, base) >= 0;
  }
  if (wanted.startsWith(">=")) {
    const base = parse(wanted.slice(2));
    return !!base && compare(parsed, base) >= 0;
  }
  return valid(value) === valid(wanted);
}

exports.valid = valid;
exports.parse = parse;
exports.satisfies = satisfies;
exports.major = function major(value) {
  const parsed = parse(value);
  return parsed ? parsed.major : null;
};
